use bhoo::android_time_clock::{TimeClockState as C,DialPart as P};
#[test] fn hours_auto_advance_on_release_even_without_change(){let mut s=C::new(15,0,false).unwrap();assert!(!s.select(90,false,false));assert_eq!(s.part(),P::Hour);assert!(!s.select(90,false,true));assert_eq!(s.part(),P::Minute);assert_eq!(s.hour(),15);}
#[test] fn twenty_four_hour_rings_map_noon_and_midnight(){let mut s=C::new(0,0,true).unwrap();s.select(0,false,false);assert_eq!(s.hour(),12);s.select(0,true,false);assert_eq!(s.hour(),0);s.select(90,true,false);assert_eq!(s.hour(),15);s.select(90,false,false);assert_eq!(s.hour(),3);}
#[test] fn minutes_snap_toward_visible_five_minute_marks(){let mut s=C::new(8,0,false).unwrap();s.set_part(P::Minute);s.select(29,false,false);assert_eq!(s.minute(),5);s.select(24,false,false);assert_eq!(s.minute(),5);s.select(20,false,false);assert_eq!(s.minute(),4);s.select(359,false,false);assert_eq!(s.minute(),0);}
mod fixture {include!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../apps/bhoo-web/src/android_time_picker_clock.rs"));}
#[test] fn xml_dial_tap_selects_hour_then_minute(){use bhoo::*;let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();s.time_clocks.insert("time_clock".into(),C::new(15,0,false).unwrap());let b=Rect{x:0.,y:0.,width:360.,height:428.};let draw=|ui:&mut Ui,s:&mut android_xml::LayoutState,input|{let mut action=None;ui.frame(input,b,0.,|f|action=fixture::LAYOUT.render(f,b,s));action};draw(&mut ui,&mut s,Input::default());let p=Some([180.,138.]);assert_eq!(draw(&mut ui,&mut s,Input{pointer:p,pressed:true,time:1.,..Input::default()}),Some("time_clock"));draw(&mut ui,&mut s,Input{pointer:p,released:true,time:1.01,..Input::default()});assert_eq!(s.time_clocks["time_clock"].hour(),12);assert_eq!(s.time_clocks["time_clock"].part(),P::Minute);let p=Some([306.,264.]);draw(&mut ui,&mut s,Input{pointer:p,pressed:true,time:1.2,..Input::default()});draw(&mut ui,&mut s,Input{pointer:p,released:true,time:1.21,..Input::default()});assert_eq!(s.time_clocks["time_clock"].minute(),15);}
#[test] fn radial_transition_crossfades_and_reduced_motion_snaps(){use bhoo::*;let b=Rect{x:0.,y:0.,width:360.,height:428.};let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();s.time_clocks.insert("time_clock".into(),C::new(3,0,false).unwrap());let draw=|ui:&mut Ui,s:&mut android_xml::LayoutState,input|ui.frame(input,b,0.,|f|{fixture::LAYOUT.render(f,b,s);});draw(&mut ui,&mut s,Input::default());let p=Some([180.,138.]);draw(&mut ui,&mut s,Input{pointer:p,pressed:true,time:1.,..Input::default()});draw(&mut ui,&mut s,Input{pointer:p,released:true,time:1.01,..Input::default()});let commands=draw(&mut ui,&mut s,Input{time:1.26,..Input::default()});let alpha=|name:&str|commands.iter().find_map(|c|if let DrawCommand::Text{text,color,..}=c {if text.as_ref()==name{Some(color.3)}else{None}}else{None}).unwrap();assert!((110..=145).contains(&alpha("1")));assert!((110..=145).contains(&alpha("05")));ui.motion_preference=MotionPreference::Reduced;let commands=draw(&mut ui,&mut s,Input{time:1.27,..Input::default()});assert!(!commands.iter().any(|c|matches!(c,DrawCommand::Text{text,..} if text.as_ref()=="1")));assert!(commands.iter().any(|c|matches!(c,DrawCommand::Text{text,..} if text.as_ref()=="05")));}
#[test] fn keyboard_mode_accepts_valid_input_and_marks_invalid(){use bhoo::*;let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();s.time_clocks.insert("time_clock".into(),C::new(15,7,false).unwrap());let b=Rect{x:0.,y:0.,width:360.,height:476.};let draw=|ui:&mut Ui,s:&mut android_xml::LayoutState,input|{let mut action=None;let commands=ui.frame(input,b,0.,|f|action=fixture::LAYOUT.render(f,b,s));(action,commands)};draw(&mut ui,&mut s,Input::default());let target=ui.semantics().iter().find(|n|n.label.as_ref()=="Type time").unwrap().bounds;let p=Some([target.x+target.width/2.,target.y+target.height/2.]);draw(&mut ui,&mut s,Input{pointer:p,pressed:true,time:1.,..Input::default()});draw(&mut ui,&mut s,Input{pointer:p,released:true,time:1.01,..Input::default()});draw(&mut ui,&mut s,Input{time:1.1,..Input::default()});assert!(ui.semantics().iter().any(|n|n.label.as_ref()=="Hour"));assert_eq!(s.text["time_clock:H"],"3");s.text.insert("time_clock:M".into(),"42".into());s.update_time_clock_input("time_clock:M");assert_eq!(s.time_clocks["time_clock"].minute(),42);assert_eq!(draw(&mut ui,&mut s,Input{time:1.2,..Input::default()}).0,Some("time_clock"));s.text.insert("time_clock:M".into(),"99".into());s.update_time_clock_input("time_clock:M");let (_,commands)=draw(&mut ui,&mut s,Input{time:1.3,..Input::default()});assert_eq!(s.time_clocks["time_clock"].minute(),42);assert!(commands.iter().any(|c|matches!(c,DrawCommand::Text{text,..} if text.as_ref()=="Invalid")));}
#[test] fn mode_toggle_uses_framework_vector_icons(){use bhoo::*;let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();s.time_clocks.insert("time_clock".into(),C::new(15,7,false).unwrap());let b=Rect{x:0.,y:0.,width:360.,height:476.};let draw=|ui:&mut Ui,s:&mut android_xml::LayoutState,input|ui.frame(input,b,0.,|f|{fixture::LAYOUT.render(f,b,s);});let commands=draw(&mut ui,&mut s,Input::default());assert!(commands.iter().any(|c|matches!(c,DrawCommand::Shape{index,..} if shape_data(*index as usize).is_some_and(|shape|shape.name=="btn_keyboard_key_material"))));let target=ui.semantics().iter().find(|n|n.label.as_ref()=="Type time").unwrap().bounds;let p=Some([target.x+target.width/2.,target.y+target.height/2.]);draw(&mut ui,&mut s,Input{pointer:p,pressed:true,time:1.,..Input::default()});draw(&mut ui,&mut s,Input{pointer:p,released:true,time:1.01,..Input::default()});let commands=draw(&mut ui,&mut s,Input{time:1.1,..Input::default()});assert!(commands.iter().any(|c|matches!(c,DrawCommand::Shape{index,..} if shape_data(*index as usize).is_some_and(|shape|shape.name=="btn_clock_material"))));}
#[test] fn clock_header_respects_hour_cycles_and_inner_midnight_is_padded(){use bhoo::*;use bhoo::android_time_spinner::HourCycle;let b=Rect{x:0.,y:0.,width:360.,height:476.};let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();s.calendar_locale.hour_cycle_12=HourCycle::H11;s.calendar_locale.hour_cycle_24=HourCycle::H24;s.time_clocks.insert("time_clock".into(),C::new(0,0,false).unwrap());let draw=|ui:&mut Ui,s:&mut android_xml::LayoutState|ui.frame(Input::default(),b,0.,|f|{fixture::LAYOUT.render(f,b,s);});let commands=draw(&mut ui,&mut s);assert!(commands.iter().any(|c|matches!(c,DrawCommand::Text{text,style,..} if text.as_ref()=="0"&&style.size==42.0)));s.time_clocks.get_mut("time_clock").unwrap().set_24_hour(true);let commands=draw(&mut ui,&mut s);assert!(commands.iter().any(|c|matches!(c,DrawCommand::Text{text,style,..} if text.as_ref()=="24"&&style.size==42.0)));assert!(commands.iter().any(|c|matches!(c,DrawCommand::Text{text,style,..} if text.as_ref()=="00"&&style.size==12.0)));}
